<?php
namespace App\Services;use App\Models\Survey;use App\Models\SurveyRun;use Illuminate\Validation\ValidationException;
class SurveyLifecycleService{
 public function start(Survey $survey,int $userId,array $device=[]):SurveyRun{if(!in_array($survey->status,['draft','ready','paused']))throw ValidationException::withMessages(['status'=>'This survey cannot be started from its current state.']);if(!$survey->floorPlan->is_active)throw ValidationException::withMessages(['floor_plan'=>'The survey floor-plan version is no longer active.']);$survey->update(['status'=>'collecting','started_at'=>$survey->started_at??now(),'lock_version'=>$survey->lock_version+1]);return $survey->runs()->create(['started_by'=>$userId,'status'=>'collecting','device_name'=>$device['device_name']??null,'device_platform'=>$device['device_platform']??null,'collector_version'=>$device['collector_version']??null,'environment'=>$device['environment']??null,'started_at'=>now()]);}
 public function validateForCompletion(Survey $survey):array{$valid=$survey->points()->where('validation_status','valid')->count();$total=$survey->points()->count();$issues=[];if($valid<$survey->minimum_points)$issues[]="At least {$survey->minimum_points} valid points are required; {$valid} available.";if(!$survey->floorPlan->pixels_per_metre)$issues[]='The floor plan must be calibrated.';if(!$survey->floorPlan->usable_boundary)$issues[]='The usable floor boundary is missing.';return compact('valid','total','issues');}
 public function complete(Survey $survey):Survey{$check=$this->validateForCompletion($survey);if($check['issues'])throw ValidationException::withMessages(['survey'=>$check['issues']]);$survey->runs()->where('status','collecting')->update(['status'=>'completed','ended_at'=>now()]);$survey->update(['status'=>'completed','completed_at'=>now(),'lock_version'=>$survey->lock_version+1]);return $survey->refresh();}
}
